import{_ as a,C as e,c as i,o as t,j as o,b as n,a0 as r,a as s,w as l,G as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Nutrición para un rendimiento de precisión","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/nutrition/index.md","filePath":"es/education/nutrition/index.md"}');const p=a({name:"es/education/nutrition/index.md"},[["render",function(a,u,p,m,b,h){const g=e("Mermaid");return t(),i("div",null,[u[2]||(u[2]=o("h1",{id:"nutricion-para-un-rendimiento-de-precision",tabindex:"-1"},[s("Nutrición para un rendimiento de precisión "),o("a",{class:"header-anchor",href:"#nutricion-para-un-rendimiento-de-precision","aria-label":'Permalink to "Nutrición para un rendimiento de precisión"'},"​")],-1)),u[3]||(u[3]=o("p",null,[s("La petanca es un deporte de precisión, no de resistencia. Tus necesidades nutricionales son diferentes a las de un maratonista o un futbolista. Lo más importante es la "),o("strong",null,"estabilidad mental"),s(": mantener la mente ágil y las manos firmes durante un largo día de competición.")],-1)),u[4]||(u[4]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"La gran idea"),o("p",null,[o("strong",null,"Tu cerebro es tu herramienta más importante en la petanca. Aliméntalo con energía estable, no con energías volátiles."),s(" Concéntrate en las proteínas, las grasas saludables y en mantenerte hidratado. Evita los picos de azúcar.")])],-1)),(t(),n(c,null,{default:l(()=>[d(g,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BAz%C3%BAcar%2FCarbohidratos%20simples%5D%20--%3E%20B%5Bpico%20de%20az%C3%BAcar%20en%20la%20sangre%5D%0A%20%20%20%20B%20--%3E%20C%5BLiberaci%C3%B3n%20de%20insulina%5D%0A%20%20%20%20C%20--%3E%20D%5BCa%C3%ADda%20del%20az%C3%BAcar%20en%20la%20sangre%5D%0A%20%20%20%20D%20--%3E%20E%5BRespuesta%20de%20adrenalina%5D%0A%20%20%20%20E%20--%3E%20F%5BTemblores%20y%20ansiedad%5D%0A%0A%20%20%20%20G%5BProte%C3%ADnas%20y%20grasas%20saludables%5D%20--%3E%20H%5BNivel%20de%20az%C3%BAcar%20en%20sangre%20estable%5D%0A%20%20%20%20H%20--%3E%20I%5BEnerg%C3%ADa%20constante%5D%0A%20%20%20%20I%20--%3E%20J%5BEnfoque%20n%C3%ADtido%5D%0A%20%20%20%20J%20--%3E%20K%5BManos%20firmes%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[5]||(u[5]=r('<h2 id="el-desafio-del-atleta-de-precision" tabindex="-1">El desafío del atleta de precisión <a class="header-anchor" href="#el-desafio-del-atleta-de-precision" aria-label="Permalink to &quot;El desafío del atleta de precisión&quot;">​</a></h2><p>A diferencia de los deportes de alta intensidad, la petanca no requiere grandes reservas de glucógeno ni una rápida reposición de energía. Lo que requiere es:</p><ul><li><strong>Azúcar en sangre estable</strong>: sin picos ni caídas</li><li><strong>Claridad mental constante</strong>: concentración que dura todo el día</li><li><strong>Manos firmes</strong> - sin temblores ni sacudidas</li><li><strong>Calma los nervios</strong> - baja respuesta a la ansiedad y al estrés</li></ul><p>Su estrategia nutricional debe optimizarse en función de estos factores, no del rendimiento energético bruto.</p><h2 id="el-problema-con-el-azucar-y-los-carbohidratos-simples" tabindex="-1">El problema con el azúcar y los carbohidratos simples <a class="header-anchor" href="#el-problema-con-el-azucar-y-los-carbohidratos-simples" aria-label="Permalink to &quot;El problema con el azúcar y los carbohidratos simples&quot;">​</a></h2><p>Muchos atletas adoptan dietas ricas en carbohidratos. Para los jugadores de petanca, esto puede perjudicar su rendimiento.</p><h3 id="la-montana-rusa-del-azucar-en-la-sangre" tabindex="-1">La montaña rusa del azúcar en la sangre <a class="header-anchor" href="#la-montana-rusa-del-azucar-en-la-sangre" aria-label="Permalink to &quot;La montaña rusa del azúcar en la sangre&quot;">​</a></h3><p>Cuando comes azúcar o carbohidratos simples:</p><ol><li>El azúcar en la sangre aumenta rápidamente</li><li>Se libera insulina para reducirla.</li><li>Bajadas repentinas de azúcar en sangre (hipoglucemia)</li><li>Tu cuerpo libera adrenalina para compensar.</li><li>Experimenta temblores, ansiedad y falta de concentración.</li></ol><p><strong>Esto es lo opuesto de lo que necesitas para lograr precisión.</strong></p><h3 id="sintomas-de-inestabilidad-del-azucar-en-sangre" tabindex="-1">Síntomas de inestabilidad del azúcar en sangre <a class="header-anchor" href="#sintomas-de-inestabilidad-del-azucar-en-sangre" aria-label="Permalink to &quot;Síntomas de inestabilidad del azúcar en sangre&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Síntoma</th><th>Impacto en el rendimiento</th></tr></thead><tbody><tr><td>Manos temblorosas</td><td>Lanzamiento inconsistente</td></tr><tr><td>Dificultad para concentrarse</td><td>Mala toma de decisiones</td></tr><tr><td>Irritabilidad</td><td>Conflicto en equipo, falta de compostura</td></tr><tr><td>Fatiga después de las comidas</td><td>Depresión de la tarde</td></tr><tr><td>Ansiedad</td><td>Sensibilidad a la presión</td></tr><tr><td>Niebla mental</td><td>Pensamiento táctico lento</td></tr></tbody></table><h2 id="un-mejor-enfoque-energia-estable" tabindex="-1">Un mejor enfoque: energía estable <a class="header-anchor" href="#un-mejor-enfoque-energia-estable" aria-label="Permalink to &quot;Un mejor enfoque: energía estable&quot;">​</a></h2><p>El objetivo es proporcionar a tu cerebro combustible constante sin que se produzcan altibajos.</p><h3 id="principios-clave" tabindex="-1">Principios clave <a class="header-anchor" href="#principios-clave" aria-label="Permalink to &quot;Principios clave&quot;">​</a></h3><ol><li><strong>Prioriza las proteínas y las grasas saludables</strong>: proporcionan energía lenta y constante.</li><li><strong>Elige carbohidratos complejos en lugar de simples</strong> - Si comes carbohidratos, elige los que se digieran lentamente.</li><li><strong>Evite los picos de azúcar</strong> - Especialmente antes y durante la competición</li><li><strong>Mantente hidratado</strong> - La deshidratación afecta significativamente la concentración.</li><li><strong>Come regularmente</strong> - No permitas que te entre demasiada hambre</li></ol><h3 id="alimentos-que-ayudan" tabindex="-1">Alimentos que ayudan <a class="header-anchor" href="#alimentos-que-ayudan" aria-label="Permalink to &quot;Alimentos que ayudan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de comida</th><th>Ejemplos</th><th>Por qué funciona</th></tr></thead><tbody><tr><td>Proteína</td><td>Huevos, nueces, queso, carne.</td><td>Digestión lenta, energía estable.</td></tr><tr><td>Grasas saludables</td><td>Aguacate, aceite de oliva, frutos secos</td><td>Combustible de larga duración</td></tr><tr><td>carbohidratos complejos</td><td>Verduras, legumbres</td><td>La fibra retarda la absorción</td></tr><tr><td>Frutas bajas en azúcar</td><td>Bayas, manzanas</td><td>Nutrientes sin pico</td></tr></tbody></table><h3 id="alimentos-que-se-deben-limitar" tabindex="-1">Alimentos que se deben limitar <a class="header-anchor" href="#alimentos-que-se-deben-limitar" aria-label="Permalink to &quot;Alimentos que se deben limitar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de comida</th><th>Ejemplos</th><th>Por qué es problemático</th></tr></thead><tbody><tr><td>Azúcar</td><td>Dulces, refrescos, pasteles</td><td>Pico rápido y caída</td></tr><tr><td>Pan blanco/pasta</td><td>Sándwiches, platos de pasta</td><td>Conversión rápida en azúcar</td></tr><tr><td>Zumo de frutas</td><td>Zumo de naranja, batidos</td><td>Azúcar concentrado</td></tr><tr><td>bebidas energéticas</td><td>La mayoría de las marcas comerciales</td><td>Caída de azúcar y cafeína</td></tr></tbody></table><h2 id="nutricion-el-dia-de-la-competicion" tabindex="-1">Nutrición el día de la competición <a class="header-anchor" href="#nutricion-el-dia-de-la-competicion" aria-label="Permalink to &quot;Nutrición el día de la competición&quot;">​</a></h2><h3 id="antes-de-la-competicion" tabindex="-1">Antes de la competición <a class="header-anchor" href="#antes-de-la-competicion" aria-label="Permalink to &quot;Antes de la competición&quot;">​</a></h3><p><strong>2-3 horas antes:</strong></p><ul><li>Comida equilibrada con proteínas, grasas y verduras.</li><li>Evite los carbohidratos pesados que pueden causar somnolencia.</li><li>Ejemplo: Huevos con verduras, o ensalada con pollo.</li></ul><p><strong>1 hora antes:</strong></p><ul><li>Refrigerio ligero si es necesario</li><li>Frutos secos, queso o una pequeña porción de proteína.</li><li>Evite cualquier cosa azucarada</li></ul><h3 id="durante-la-competicion" tabindex="-1">Durante la competición <a class="header-anchor" href="#durante-la-competicion" aria-label="Permalink to &quot;Durante la competición&quot;">​</a></h3><p><strong>Entre juegos:</strong></p><ul><li>Agua (lo más importante)</li><li>Pequeños snacks proteicos (frutos secos, queso, carne)</li><li>Evite los snacks y bebidas azucaradas.</li></ul><p><strong>Señales de que necesitas comer:</strong></p><ul><li>Dificultad para concentrarse</li><li>Irritabilidad</li><li>Sentirse tembloroso</li><li>Dolor de cabeza</li></ul><h3 id="despues-de-la-competicion" tabindex="-1">Después de la competición <a class="header-anchor" href="#despues-de-la-competicion" aria-label="Permalink to &quot;Después de la competición&quot;">​</a></h3><ul><li>Repóngase con una comida equilibrada</li><li>Rehidratarse completamente</li><li>No te &quot;premies&quot; con azúcar: afectará tu recuperación.</li></ul><h2 id="hidratacion" tabindex="-1">Hidratación <a class="header-anchor" href="#hidratacion" aria-label="Permalink to &quot;Hidratación&quot;">​</a></h2><p>La deshidratación afecta la función cognitiva antes de sentir sed.</p><h3 id="pautas" tabindex="-1">Pautas <a class="header-anchor" href="#pautas" aria-label="Permalink to &quot;Pautas&quot;">​</a></h3><ul><li><strong>Empieza hidratado</strong> - Bebe agua durante todo el día antes de la competición.</li><li><strong>Durante el juego</strong> - Beba agua regularmente, no espere a tener sed.</li><li><strong>Evite el exceso de cafeína</strong> - Es diurético.</li><li><strong>Esté atento a las señales</strong>: dolor de cabeza, orina oscura, fatiga</li></ul><h3 id="¿cuanto-cuesta" tabindex="-1">¿Cuánto cuesta? <a class="header-anchor" href="#¿cuanto-cuesta" aria-label="Permalink to &quot;¿Cuánto cuesta?&quot;">​</a></h3><p>Como regla general, busque orina de color amarillo pálido. Si es oscura, necesita más agua.</p><h2 id="la-opcion-baja-en-carbohidratos" tabindex="-1">La opción baja en carbohidratos <a class="header-anchor" href="#la-opcion-baja-en-carbohidratos" aria-label="Permalink to &quot;La opción baja en carbohidratos&quot;">​</a></h2><p>Algunos atletas de precisión adoptan dietas bajas en carbohidratos o cetogénicas. La teoría:</p><p><strong>Beneficios potenciales:</strong></p><ul><li>Nivel de azúcar en sangre muy estable (sin picos posibles)</li><li>Claridad mental constante</li><li>Reducción de la ansiedad y los temblores.</li><li>Sin bajones de energía por la tarde</li></ul><p><strong>Consideraciones:</strong></p><ul><li>Requiere período de adaptación (1-2 semanas)</li><li>No apto para todos</li><li>Requiere planificación y compromiso</li><li>Consulte primero con un proveedor de atención médica</li></ul><p>Esta es una estrategia avanzada, no necesaria para todos, pero que vale la pena considerar si la estabilidad del nivel de azúcar en sangre es un problema importante para usted.</p><h2 id="la-alimentacion-como-practica-entrenando-tu-cuerpo" tabindex="-1">La alimentación como práctica: entrenando tu cuerpo <a class="header-anchor" href="#la-alimentacion-como-practica-entrenando-tu-cuerpo" aria-label="Permalink to &quot;La alimentación como práctica: entrenando tu cuerpo&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Concepto crítico</p><p><strong>La comida no es solo combustible: es algo con lo que practicas.</strong> Al igual que practicas tu lanzamiento, debes practicar tu nutrición para que tu cuerpo se sienta cómodo con la alimentación del día de la competencia.</p></div><h3 id="por-que-son-importantes-las-practicas-alimentarias" tabindex="-1">Por qué son importantes las prácticas alimentarias <a class="header-anchor" href="#por-que-son-importantes-las-practicas-alimentarias" aria-label="Permalink to &quot;Por qué son importantes las prácticas alimentarias&quot;">​</a></h3><p>Tu sistema digestivo se puede entrenar. Lo que comes regularmente se convierte en lo que tu cuerpo espera y procesa mejor. Si solo comes proteínas y verduras los días de competición, tu cuerpo no se adaptará.</p><p><strong>El problema:</strong></p><ul><li>Comer alimentos desconocidos el día de la competición puede provocar molestias digestivas.</li><li>Tu cuerpo necesita tiempo para adaptarse a nuevos patrones de alimentación.</li><li>Estrés + comida desconocida = posibles problemas estomacales</li><li>La ansiedad por el rendimiento ya es bastante mala sin añadirle ansiedad digestiva.</li></ul><p><strong>La solución:</strong></p><ul><li>Practica tu nutrición de competición durante el entrenamiento</li><li>Haga que las comidas del día de la competencia formen parte de su rutina habitual</li><li>Entrena tu cuerpo para que se sienta cómodo con alimentos de energía estable</li></ul><h3 id="el-proceso-de-adaptacion" tabindex="-1">El proceso de adaptación <a class="header-anchor" href="#el-proceso-de-adaptacion" aria-label="Permalink to &quot;El proceso de adaptación&quot;">​</a></h3>',55)),(t(),n(c,null,{default:l(()=>[d(g,{id:"mermaid-586",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDieta%20actual%5D%20--%3E%20B%5BCambios%20graduales%5D%0A%20%20%20%20B%20--%3E%20C%5BAdaptaci%C3%B3n%20corporal%20%3Cbr%2F%3E%202-4%20semanas%5D%0A%20%20%20%20C%20--%3E%20D%5BNueva%20normalidad%5D%0A%20%20%20%20D%20--%3E%20E%5BListo%20para%20la%20competencia%5D%0A%0A%20%20%20%20F%5BCambio%20repentino%20%3Cbr%2F%3E%20D%C3%ADa%20de%20la%20competici%C3%B3n%5D%20--%3E%20G%5BMalestar%20digestivo%5D%0A%20%20%20%20G%20--%3E%20H%5BBajo%20rendimiento%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:l(()=>[...u[1]||(u[1]=[s(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=r('<p>Cuando cambias tu dieta:</p><ol><li><strong>Semana 1-2:</strong> Tu cuerpo se adapta a nuevos alimentos, puede sentirse diferente</li><li><strong>Semana 3-4:</strong> Se produce la adaptación, los nuevos alimentos se sienten normales.</li><li><strong>Semana 5+:</strong> Tu cuerpo se siente cómodo y eficiente con estos alimentos</li></ol><p><strong>Es por esto que no puedes simplemente &quot;comer sano&quot; el día de la competencia y esperar resultados óptimos.</strong></p><h3 id="como-practicar-tu-nutricion" tabindex="-1">Cómo practicar tu nutrición <a class="header-anchor" href="#como-practicar-tu-nutricion" aria-label="Permalink to &quot;Cómo practicar tu nutrición&quot;">​</a></h3><h4 id="_1-comienza-durante-el-entrenamiento" tabindex="-1">1. Comienza durante el entrenamiento <a class="header-anchor" href="#_1-comienza-durante-el-entrenamiento" aria-label="Permalink to &quot;1. Comienza durante el entrenamiento&quot;">​</a></h4><p><strong>Practica tu alimentación el día de la competición durante las sesiones de entrenamiento:</strong></p><ul><li>Come la misma comida previa al entrenamiento que comerías antes de la competición.</li><li>Lleva los mismos bocadillos que llevarías a un torneo.</li><li>Observa cómo responde tu cuerpo</li><li>Ajuste según lo que funcione</li></ul><p><strong>Ejemplo de día de formación:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-hazlo-tu-normalidad" tabindex="-1">2. Hazlo tu normalidad <a class="header-anchor" href="#_2-hazlo-tu-normalidad" aria-label="Permalink to &quot;2. Hazlo tu normalidad&quot;">​</a></h4><p><strong>No tener una &quot;dieta de competición&quot; y una &quot;dieta regular&quot;</strong> - esto crea dos problemas:</p><ul><li>Tu cuerpo nunca se adapta completamente a ninguno de los dos.</li><li>La comida de competición resulta desconocida y estresante.</li></ul><p><strong>En cambio:</strong></p><ul><li>Haga de los alimentos de energía estable su norma diaria</li><li>Tu cuerpo se vuelve eficiente en el uso de proteínas y grasas.</li><li>El día de competición se siente normal, no diferente.</li><li>Sin sorpresas digestivas</li></ul><h4 id="_3-probar-y-refinar" tabindex="-1">3. Probar y refinar <a class="header-anchor" href="#_3-probar-y-refinar" aria-label="Permalink to &quot;3. Probar y refinar&quot;">​</a></h4><p><strong>Utilice el entrenamiento para experimentar:</strong></p><table tabindex="0"><thead><tr><th>Prueba</th><th>Qué tener en cuenta</th><th>Ajustar</th></tr></thead><tbody><tr><td>Horario de comidas antes del entrenamiento</td><td>Niveles de energía, enfoque</td><td>Encuentra tu ventana óptima</td></tr><tr><td>Diferentes fuentes de proteínas</td><td>Digestión, comodidad</td><td>Identificar lo que funciona mejor</td></tr><tr><td>Tipos de snacks</td><td>Energía sostenida</td><td>Encuentra tus snacks favoritos</td></tr><tr><td>Cantidades de hidratación</td><td>Concentración, pausas para ir al baño</td><td>Ingesta de equilibrio</td></tr></tbody></table><p><strong>Mantenga un registro simple:</strong></p><ul><li>Qué comiste y cuándo</li><li>¿Cómo te sentiste durante el entrenamiento?</li><li>Niveles de energía y concentración</li><li>¿Algún problema digestivo?</li></ul><h4 id="_4-genere-comodidad-y-confianza" tabindex="-1">4. Genere comodidad y confianza <a class="header-anchor" href="#_4-genere-comodidad-y-confianza" aria-label="Permalink to &quot;4. Genere comodidad y confianza&quot;">​</a></h4><p><strong>El beneficio psicológico:</strong></p><p>Cuando has practicado tu nutrición cientos de veces en el entrenamiento:</p><ul><li>Sabes exactamente cómo responderá tu cuerpo</li><li>Sin ansiedad por la elección de alimentos</li><li>Una cosa menos de la que preocuparse el día de la competición</li><li>Confianza en tu preparación</li></ul><p><strong>Este es el mismo principio que practicar el lanzamiento</strong>: la repetición genera comodidad y confiabilidad.</p><h3 id="desafios-comunes-de-adaptacion" tabindex="-1">Desafíos comunes de adaptación <a class="header-anchor" href="#desafios-comunes-de-adaptacion" aria-label="Permalink to &quot;Desafíos comunes de adaptación&quot;">​</a></h3><details class="details custom-block"><summary>Transición de una dieta alta en carbohidratos a una dieta de energía estable</summary><p><strong>Desafío:</strong> Estás acostumbrado al pan, la pasta y los bocadillos azucarados.</p><p><strong>Periodo de adaptación:</strong> 2-4 semanas</p><p><strong>Qué esperar:</strong></p><ul><li>Semana 1: Puede sentirse diferente, antojos de alimentos viejos.</li><li>Semana 2: La energía se estabiliza, los antojos se reducen.</li><li>Semana 3-4: Nueva normalidad, cuerpo eficiente con grasas/proteínas</li></ul><p><strong>Cómo practicar:</strong></p><ul><li>Comience con una comida a la vez</li><li>Reemplace primero los carbohidratos simples con carbohidratos complejos</li><li>Aumente gradualmente las proteínas y las grasas saludables.</li><li>Practique primero durante el entrenamiento de bajo riesgo</li></ul></details><details class="details custom-block"><summary>Cómo encontrar alimentos que funcionen para usted</summary><p><strong>Desafío:</strong> No todos digieren bien los mismos alimentos</p><p><strong>Qué probar:</strong></p><ul><li>Diferentes fuentes de proteínas (huevos, carne y frutos secos)</li><li>Horario de las comidas (2 horas vs. 3 horas antes)</li><li>Tamaño de las porciones (demasiado = lento, muy poco = hambriento)</li><li>Alimentos específicos que causan malestar</li></ul><p><strong>Enfoque práctico:</strong></p><ul><li>Pruebe una variable a la vez</li><li>Dar a cada prueba 2-3 sesiones de entrenamiento</li><li>Toma nota de lo que te hace sentir mejor</li><li>Crea tu &quot;menú de competición&quot; personal</li></ul></details><details class="details custom-block"><summary>Cómo lidiar con los entornos alimentarios de los torneos</summary><p><strong>Desafío:</strong> Los torneos suelen tener opciones de comida limitadas.</p><p><strong>Solución práctica:</strong></p><ul><li>Lleva siempre tus propios snacks (practica esto)</li><li>Explorar los lugares con antelación cuando sea posible</li><li>Tiene opciones de respaldo que sabe que funcionan</li><li>Practica comer en diferentes entornos</li></ul><p><strong>Preparación mental:</strong></p><ul><li>No confíes en la comida del local</li><li>Trate los alimentos como parte de su equipo</li><li>Empáquelo como empaqueta sus petancas</li></ul></details><h3 id="el-plan-de-practica-nutricional-de-30-dias" tabindex="-1">El plan de práctica nutricional de 30 días <a class="header-anchor" href="#el-plan-de-practica-nutricional-de-30-dias" aria-label="Permalink to &quot;El plan de práctica nutricional de 30 días&quot;">​</a></h3><p><strong>Objetivo:</strong> Hacer que comer con energía estable sea una rutina cómoda</p><p><strong>Semana 1-2: Fundación</strong></p><ul><li>Reemplace una comida al día con una alimentación de estilo competitivo.</li><li>Practica la nutrición pre-entrenamiento</li><li>Empieza a llevar snacks a los entrenamientos</li><li>Observa cómo responde tu cuerpo</li></ul><p><strong>Semana 3-4: Expansión</strong></p><ul><li>Realice dos comidas al día centradas en energía estable.</li><li>Practique la alimentación completa del día de competición en los días de entrenamiento</li><li>Refina tus elecciones de refrigerios</li><li>Crea tu lista de alimentos favoritos</li></ul><p><strong>Semana 5+: Maestría</strong></p><ul><li>Comer con energía estable es tu nueva normalidad</li><li>El cuerpo está completamente adaptado.</li><li>El día de competición se siente rutinario</li><li>Confianza en tu nutrición</li></ul><h3 id="tu-kit-de-comida-para-la-competicion" tabindex="-1">Tu kit de comida para la competición <a class="header-anchor" href="#tu-kit-de-comida-para-la-competicion" aria-label="Permalink to &quot;Tu kit de comida para la competición&quot;">​</a></h3><p><strong>Practica preparar este paquete para cada sesión de entrenamiento:</strong></p><p><strong>Pre-competición (2-3 horas antes):</strong></p><ul><li>[ ] Fuente de proteínas (huevos, carne o frutos secos)</li><li>[ ] Verduras o ensalada</li><li>[ ] Grasas saludables (aguacate, aceite de oliva, queso)</li></ul><p><strong>Durante la competición:</strong></p><ul><li>[ ] Botella de agua (rellenable)</li><li>[ ] Frutos secos mixtos (pequeñas porciones)</li><li>[ ] Huevos duros (si puedes mantenerlos frescos)</li><li>[ ] Cubitos de queso o queso en tiras</li><li>[ ] Carne seca o cecina</li><li>[ ] Snacks de respaldo</li></ul><p><strong>Cuanto más practiques con este kit, más automático se volverá.</strong></p><h2 id="consejos-practicos" tabindex="-1">Consejos prácticos <a class="header-anchor" href="#consejos-practicos" aria-label="Permalink to &quot;Consejos prácticos&quot;">​</a></h2><h3 id="snacks-faciles-para-la-competicion" tabindex="-1">Snacks fáciles para la competición <a class="header-anchor" href="#snacks-faciles-para-la-competicion" aria-label="Permalink to &quot;Snacks fáciles para la competición&quot;">​</a></h3><ul><li>Frutos secos mixtos (sin sal)</li><li>huevos duros</li><li>Cubitos de queso</li><li>Cecina de res o pavo</li><li>Verduras con hummus</li><li>Aceitunas</li></ul><h3 id="que-evitar" tabindex="-1">Qué evitar <a class="header-anchor" href="#que-evitar" aria-label="Permalink to &quot;Qué evitar&quot;">​</a></h3><ul><li>Snacks de máquinas expendedoras</li><li>bebidas deportivas azucaradas</li><li>Pasteles y productos horneados</li><li>Barras de caramelo y chocolate</li><li>La mayoría de las barritas &quot;energéticas&quot; (verificar el contenido de azúcar)</li></ul><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Tu cerebro es tu herramienta más importante en la petanca. Aliméntalo con energía estable, no con la energía de una montaña rusa. Y practica tu nutrición como practicas tu lanzamiento: la repetición genera comodidad y fiabilidad.</p></blockquote><p>Concéntrate en las proteínas, las grasas saludables y en mantenerte hidratado. Evita los picos de azúcar. <strong>Lo más importante: integra tu alimentación diaria con la del día de la competición.</strong> Tu cuerpo necesita práctica para rendir al máximo.</p><p><strong>Recuerda:</strong> No te presentarías a un torneo con una técnica de lanzamiento que nunca hayas practicado. Tampoco te presentes con una estrategia nutricional que nunca hayas practicado.</p>',52))])}]]);export{u as __pageData,p as default};
